def sha(p):
    with open(os.path.join(ROOT, p), "rb") as f:
        return hashlib.sha256(f.read()).hexdigest()
bad = 0
for a, b in PAIRS:
    try:
        ok = sha(a) == sha(b)
    except FileNotFoundError as e:
        ok = False; print("MISSING:", e)
    if not ok:
        bad += 1; print("DIFFERENT:", a, "<->", b)
print("shared documents checked:", len(PAIRS), "| differences:", bad)
sys.exit(1 if bad else 0)
